<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';require_method('POST');$u=require_role('OWNER','ADMIN');require_csrf();$d=input();rate_limit('smtp_test_save',$u['tenant_id'].':'.$u['id'],10,3600);
$host=strtolower(string_value($d,'host',255));assert_safe_smtp_host($host);$email=email_value($d,'senderEmail');$testEmail=email_value($d,'testEmail');$enc=strtolower((string)($d['encryption']??'tls'));if(!in_array($enc,['tls','ssl'],true))throw new ApiError(422,'Security must be SSL or TLS.');$password=(string)($d['password']??'');if($password===''||strlen($password)>1000)throw new ApiError(422,'SMTP password is required.');
$account=['host'=>$host,'port'=>int_value($d,'port',1,65535),'encryption'=>$enc,'username'=>string_value($d,'username',255),'password'=>$password,'sender_email'=>$email,'sender_name'=>string_value($d,'senderName',100,false)??$u['full_name']];
try{MailService::testCustomerAccount($account,$testEmail);}catch(Throwable $e){$safe=mb_substr(preg_replace('/(password|auth|credential)[^\s]*/i','[redacted]',$e->getMessage())??'SMTP connection or delivery failed',0,500);audit('smtp.test_save_failed','smtp_account',null,['host'=>$host,'diagnostic'=>$safe]);throw new ApiError(422,'SMTP connection or test email failed. The account was not saved.',['diagnostic'=>$safe]);}
$replyTracking=filter_var($d['replyTracking']??false,FILTER_VALIDATE_BOOL);$imapHost=null;$imapPort=null;$imapEncryption=null;$imapUsername=null;$imapPasswordCiphertext=null;
if($replyTracking){require_once dirname(__DIR__).'/services/ReplyMailboxService.php';$imapHost=strtolower(string_value($d,'imapHost',255));assert_safe_smtp_host($imapHost);$imapEncryption=strtolower((string)($d['imapEncryption']??'ssl'));if(!in_array($imapEncryption,['ssl','tls','none'],true))throw new ApiError(422,'IMAP security must be SSL, TLS, or none.');$imapPort=int_value($d,'imapPort',1,65535,993);$imapUsername=string_value($d,'imapUsername',255,false)??$account['username'];$imapPassword=(string)($d['imapPassword']??'');if($imapPassword==='')$imapPassword=$password;try{ReplyMailboxService::test(['imap_host'=>$imapHost,'imap_port'=>$imapPort,'imap_encryption'=>$imapEncryption,'imap_username'=>$imapUsername,'imap_password'=>$imapPassword]);}catch(Throwable $e){$safe=ReplyMailboxService::safeError($e->getMessage());throw new ApiError(422,'SMTP test passed, but the inbox connection failed. The account was not saved.',['diagnostic'=>$safe]);}$imapPasswordCiphertext=encrypt_secret($imapPassword);}
$enabled=filter_var($d['enableSending']??true,FILTER_VALIDATE_BOOL);$dailyLimit=min(500,int_value($d,'dailyLimit',1,500,500));$id=uuid();db()->prepare("INSERT INTO smtp_accounts (tenant_id,public_id,account_name,sender_name,sender_email,host,port,encryption,username,password_ciphertext,status,is_active,daily_limit,hourly_limit,per_minute_limit,sending_interval_seconds,last_tested_at,reply_tracking_enabled,imap_host,imap_port,imap_encryption,imap_username,imap_password_ciphertext) VALUES (?,?,?,?,?,?,?,?,?,?,'CONNECTED',?,?,?,?,?,UTC_TIMESTAMP(),?,?,?,?,?,?)")->execute([$u['tenant_id'],$id,string_value($d,'accountName',100,false)??$email,$account['sender_name'],$email,$host,$account['port'],$enc,$account['username'],encrypt_secret($password),$enabled?1:0,$dailyLimit,int_value($d,'hourlyLimit',1,10000,100),int_value($d,'perMinuteLimit',1,1000,10),1,$replyTracking?1:0,$imapHost,$imapPort,$imapEncryption,$imapUsername,$imapPasswordCiphertext]);audit('smtp.tested_and_added','smtp_account',$id,['testRecipient'=>$testEmail,'enabled'=>$enabled,'replyTracking'=>$replyTracking]);respond(['id'=>$id,'status'=>'CONNECTED','isActive'=>$enabled,'message'=>'Test email sent and SMTP account saved securely.'],201);
